// src/tasks/tasks.js
import {tasks, renderTask} from "./taskManager.js";
import {currentProjectId, projects} from "../projects/projectManager.js";
export {loadTasks};

function loadTasks(){
    const container = document.createElement('div')
    container.classList.add("container");

    const title = currentProjectId ? `Project: ${projects.find(project => project.id === currentProjectId)?.title}` : "Tasks";

    container.innerHTML = `
        <h2>${title}</h2>
        <button id="addTask"><svg xmlns="http://www.w3.org/2000/svg" height="24px" viewBox="0 -960 960 960" width="24px" fill="#000000"><path d="M680-40v-120H560v-80h120v-120h80v120h120v80H760v120h-80ZM200-200v-560 560Zm0 80q-33 0-56.5-23.5T120-200v-560q0-33 23.5-56.5T200-840h560q33 0 56.5 23.5T840-760v353q-18-11-38-18t-42-11v-324H200v560h280q0 21 3 41t10 39H200Zm148.5-171.5Q360-303 360-320t-11.5-28.5Q337-360 320-360t-28.5 11.5Q280-337 280-320t11.5 28.5Q303-280 320-280t28.5-11.5Zm0-160Q360-463 360-480t-11.5-28.5Q337-520 320-520t-28.5 11.5Q280-497 280-480t11.5 28.5Q303-440 320-440t28.5-11.5Zm0-160Q360-623 360-640t-11.5-28.5Q337-680 320-680t-28.5 11.5Q280-657 280-640t11.5 28.5Q303-600 320-600t28.5-11.5ZM440-440h240v-80H440v80Zm0-160h240v-80H440v80Zm0 320h54q8-23 20-43t28-37H440v80Z"/></svg>Add Task</button>
        <div class="tasks-container"></div>
    `;

    setTimeout(() => {
        const filteredTasks = tasks.filter(tasks => tasks.projectId === currentProjectId);
        filteredTasks.forEach(task => renderTask(task));
    }, 0);

    return container;
}